SET NOCOUNT ON;
SET STATISTICS IO ON;
SET STATISTICS TIME ON;
SELECT ZoneName = (SELECT Z.Name FROM Zone Z WHERE Z.ZoneCode = 1), ZoneName2 = (SELECT Z.Name FROM Zone Z WHERE Z.ZoneCode = 1), Icode=St.Icode, AliasName= i.customicode, Itemname = i.name, GroupCode=CASE 'M' WHEN 'M' THEN I.MANFCODE WHEN 'C' THEN I.ICatCode WHEN 'L' THEN I.ICCode ELSE I.PACKCODE END, GroupName= CASE 'M' WHEN 'M' THEN (SELECT M.NAME FROM MANUFACTURER M WHERE M.MANFCODE = I.ManfCode) WHEN 'C' THEN (SELECT C.NAME FROM ITEMCATEGORY C WHERE C.ICATCODE = I.ICatCode) WHEN 'L' THEN (SELECT C.NAME FROM ITEMCLASS C WHERE C.ICCODE = I.ICCode) ELSE (SELECT P.NAME FROM ITEMPACKING P WHERE P.PACKCODE = I.PACKCODE) END, Rate= CASE 1 WHEN 1 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) ELSE ROUND(I.AVGPRICE, 2) END, packingdesc= max(i.packingdesc), openqty = SUM(CASE WHEN type='OP' THEN qty ELSE 0 END), openvalue = ROUND(SUM(CASE WHEN type='OP' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * qty WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * qty ELSE ROUND(I.AVGPRICE, 2) * qty END ELSE 0 END), 0), PurQty = SUM(CASE WHEN type='PV' THEN (Qty+Bonus) ELSE 0 END), PurValue = ROUND(SUM( CASE WHEN type='PV' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (qty + bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (qty + bonus) ELSE ROUND(I.AVGPRICE, 2) * (qty + bonus) END ELSE 0 END), 0), PRetQty =SUM(CASE WHEN type='PR' THEN (Qty + Bonus) ELSE 0 END), PRetValue =ROUND(SUM(CASE WHEN type='PR' THEN value ELSE 0 END), 0), ZoneSaleQty = SUM(CASE WHEN type='SV' THEN (Qty + Bonus) ELSE 0 END), ZoneSaleValue = ROUND(SUM( CASE WHEN type='SV' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), 0), OtherSaleQty= SUM(CASE WHEN type='S2' THEN (Qty + Bonus) ELSE 0 END), OtherSaleValue = ROUND(SUM( CASE WHEN type='S2' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), 0), ZoneSRetQty = SUM(CASE WHEN type='SR' THEN (Qty + Bonus) ELSE 0 END), ZoneSRetValue = ROUND(SUM(CASE WHEN type='SR' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), 0), OtherSRetQty = SUM(CASE WHEN type='R2' THEN (Qty + Bonus) ELSE 0 END), OtherSRetValue = ROUND(SUM(CASE WHEN type='R2' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), 0), ZoneSaleQty2 = SUM(CASE WHEN type='S1' THEN (Qty + Bonus) ELSE 0 END), ZoneSaleValue2 = ROUND(SUM( CASE WHEN type='S1' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), 0), ZoneSRetQty2 = SUM(CASE WHEN type='R1' THEN (Qty + Bonus) ELSE 0 END), ZoneSRetValue2 = ROUND(SUM(CASE WHEN type='R1' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), 0), IssueQty =SUM(CASE WHEN type='IV' THEN (Qty + Bonus) ELSE 0 END), IssueValue=SUM(CASE WHEN type='IV' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), DueSatisfyQty =SUM(CASE WHEN type='DS' THEN (Qty + Bonus) ELSE 0 END), DueSatisfyValue=SUM(CASE WHEN type='DS' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), ReceiptQty=SUM(CASE WHEN type='RV' THEN (Qty + Bonus) ELSE 0 END), ReceiptValue=SUM(CASE WHEN type='RV' THEN CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END ELSE 0 END), AdjQty =SUM(CASE WHEN type='AI' THEN (Qty + Bonus) WHEN type='AD' THEN -(Qty + Bonus) ELSE 0 END), AdjValue =SUM(CASE WHEN type='AI' THEN (CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END) WHEN type='AD' THEN -(CASE 1 WHEN 1 THEN value WHEN 2 THEN ROUND(I.SALEPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) WHEN 3 THEN ROUND(I.PURPRICE / CASE I.PACKUNITS WHEN 0 THEN 1 ELSE I.PACKUNITS END, 2) * (Qty + Bonus) ELSE ROUND(I.AVGPRICE, 2) * (Qty + Bonus) END) ELSE 0 END) FROM Item I LEFT OUTER JOIN (SELECT type='OP', icode, date=null, qty = sum(qty), bonus = 0, value=0 FROM (select pd.icode, qty = sum(isnull(case pl.purcatcode when 1 THEN (packqty + bonusqty) * packunits when 2 THEN (packqty + bonusqty) * packunits else looseqty + bonusqty end, 0)) FROM purledger pl, purdetail pd WHERE pl.posted = 'Y' AND pl.purinvcode = pd.purinvcode AND pl.date < '2024-01-01' Group By pd.icode UNION ALL select pd.icode, qty = - sum(pd.looseqty + pd.bonusqty + pd.packqty * pd.packunits) FROM prledger pl, prdetail pd WHERE pl.posted = 'Y' AND pl.prinvcode = pd.prinvcode AND pl.date < '2024-01-01' Group By pd.icode UNION ALL select sd.icode, qty = -sum(sd.looseqty + sd.bonusqty) FROM saleledger sl, saledetail sd WHERE sl.saleinvcode = sd.saleinvcode AND sl.date < '2024-01-01' AND sd.Due IS NULL Group By sd.icode UNION ALL select sd.icode, qty = sum(sd.looseqty + sd.bonusqty) FROM srledger sl, srdetail sd WHERE sl.posted = 'Y' AND sl.srinvcode = sd.srinvcode AND sl.date < '2024-01-01' Group By sd.icode UNION ALL select sd.icode, qty = -sum(sd.qty) FROM issueheader sl, issuedetail sd WHERE sl.issueinvcode = sd.issueinvcode AND sl.date < '2024-01-01' Group By sd.icode UNION ALL select sd.icode, qty = sum(sd.qty) FROM receiptheader sl, receiptdetail sd WHERE sl.posted = 'Y' AND sl.receiptinvcode = sd.receiptinvcode AND sl.date < '2024-01-01' Group By sd.icode UNION ALL select sd.icode, qty = sum(sd.looseqty) FROM Adjheader sl, Adjdetail sd WHERE sl.posted = 'Y' AND sl.Adjcode = sd.Adjcode and sl.Adjcatcode = 1 AND sl.date < '2024-01-01' Group By sd.icode UNION ALL select sd.icode, qty = -sum(sd.looseqty) FROM Adjheader sl, Adjdetail sd WHERE sl.posted = 'Y' AND sl.Adjcode = sd.Adjcode and sl.Adjcatcode = 2 AND sl.date < '2024-01-01' Group By sd.icode UNION ALL select d.icode, qty = -sum(d.duesatisfyqty) FROM duesatisfyheader h, duesatisfydetail d WHERE h.duesatisfycode=d.duesatisfycode AND h.duesatisfydate < '2024-01-01' Group By d.icode) A GROUP BY icode UNION ALL select type='PV', pd.icode, pl.date, qty = sum(looseqty + packqty * packunits), bonus = sum(isnull(case pl.purcatcode when 1 THEN bonusqty * packunits when 2 THEN bonusqty * packunits else bonusqty end, 0)), value = sum(isnull(case pl.purcatcode when 1 THEN (packqty + bonusqty) when 2 THEN (packqty + bonusqty) else looseqty + bonusqty end, 0) * pd.purprice * (1 - pd.discperc * 0.01) * (1 - pl.discperc * 0.01)) FROM purledger pl, purdetail pd WHERE pl.posted = 'Y' AND pl.purinvcode = pd.purinvcode AND pl.date >= '2024-01-01' and pl.date <= '2024-01-07' Group By pd.icode, pl.date UNION ALL select type='PR', pd.icode, pl.date, qty = sum(pd.looseqty + pd.packqty * pd.packunits), bonus = sum(bonusqty), value = sum((pd.looseqty + pd.bonusqty + pd.packqty * pd.packunits) * pd.prprice * (1 - pd.discperc * 0.01) * (1 - pl.discperc * 0.01)) FROM prledger pl, prdetail pd WHERE pl.posted = 'Y' AND pl.prinvcode = pd.prinvcode AND pl.date >= '2024-01-01' and pl.date <= '2024-01-07' Group By pd.icode, pl.date UNION ALL select type='SV', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = sum(bonusqty), value = sum((sd.looseqty + sd.bonusqty) * (sd.saleprice - sd.itemflatdisc) * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01)) FROM saleledger sl, saledetail sd, zone z, zoneareas za, customer c WHERE z.zonecode = 1 AND z.zonecode = za.zonecode AND za.areacode = c.areacode AND c.custcode = sl.custcode AND sl.posted = 'Y' AND sl.date BETWEEN '2024-01-01' and '2024-01-07' AND sl.saleinvcode = sd.saleinvcode AND sd.Due IS NULL Group By sd.icode, sl.date UNION ALL select type='SR', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = sum(bonusqty), value = sum((sd.looseqty + sd.bonusqty) * sd.srprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01)) FROM srledger sl, srdetail sd, zone z, zoneareas za, customer c WHERE z.zonecode = 1 AND z.zonecode = za.zonecode AND za.areacode = c.areacode AND c.custcode = sl.custcode AND sl.posted = 'Y' AND sl.date BETWEEN '2024-01-01' and '2024-01-07' AND sl.srinvcode = sd.srinvcode Group By sd.icode, sl.date UNION ALL select type='S1', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = sum(bonusqty), value = sum((sd.looseqty + sd.bonusqty) * (sd.saleprice - sd.itemflatdisc) * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01)) FROM saleledger sl, saledetail sd, zone z, zoneareas za, customer c WHERE z.zonecode = 1 AND z.zonecode = za.zonecode AND za.areacode = c.areacode AND c.custcode = sl.custcode AND sl.posted = 'Y' AND sl.date BETWEEN '2024-01-01' and '2024-01-07' AND sl.saleinvcode = sd.saleinvcode AND sd.Due IS NULL Group By sd.icode, sl.date UNION ALL select type='R1', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = sum(bonusqty), value = sum((sd.looseqty + sd.bonusqty) * sd.srprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01)) FROM srledger sl, srdetail sd, zone z, zoneareas za, customer c WHERE z.zonecode = 1 AND z.zonecode = za.zonecode AND za.areacode = c.areacode AND c.custcode = sl.custcode AND sl.posted = 'Y' AND sl.date BETWEEN '2024-01-01' and '2024-01-07' AND sl.srinvcode = sd.srinvcode Group By sd.icode, sl.date UNION ALL select type='S2', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = sum(bonusqty), value = sum((sd.looseqty + sd.bonusqty) * (sd.saleprice - sd.itemflatdisc) * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01)) FROM saleledger sl, saledetail sd, customer c WHERE c.areacode NOT IN (SELECT za.areacode FROM zone z, zoneareas za WHERE z.zonecode = 1 AND z.zonecode = za.zonecode UNION SELECT za.areacode FROM zone z, zoneareas za WHERE z.zonecode = 1 AND z.zonecode = za.zonecode) AND c.custcode = sl.custcode AND sl.posted = 'Y' AND sl.date BETWEEN '2024-01-01' and '2024-01-07' AND sl.saleinvcode = sd.saleinvcode AND sd.Due IS NULL Group By sd.icode, sl.date UNION ALL select type='R2', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = sum(bonusqty), value = sum((sd.looseqty + sd.bonusqty) * sd.srprice * (1 - sd.discperc * 0.01) * (1 - sl.discperc * 0.01)) FROM srledger sl, srdetail sd, customer c WHERE c.areacode NOT IN (SELECT za.areacode FROM zone z, zoneareas za WHERE z.zonecode = 1 AND z.zonecode = za.zonecode UNION SELECT za.areacode FROM zone z, zoneareas za WHERE z.zonecode = 1 AND z.zonecode = za.zonecode) AND c.custcode = sl.custcode AND sl.posted = 'Y' AND sl.date BETWEEN '2024-01-01' and '2024-01-07' AND sl.srinvcode = sd.srinvcode Group By sd.icode, sl.date UNION ALL select type='IV', sd.icode, sl.date, qty = sum(sd.qty), bonus = 0, value = sum(sd.qty * sd.saleprice) FROM issueheader sl, issuedetail sd WHERE sl.posted = 'Y' AND sl.issueinvcode = sd.issueinvcode AND sl.date >= '2024-01-01' and sl.date <= '2024-01-07' Group By sd.icode, sl.date UNION ALL select type='DS', d.icode, date=h.duesatisfydate, qty = sum(d.duesatisfyqty), bonus = 0, value = sum(d.duesatisfyqty * (d.packsaleprice / case d.packunits when 0 then 1 else d.packunits end)) FROM duesatisfyheader h, duesatisfydetail d WHERE h.duesatisfycode = d.duesatisfycode AND h.duesatisfydate >= '2024-01-01' and h.duesatisfydate <= '2024-01-07' Group By d.icode, h.duesatisfydate UNION ALL select type='RV', sd.icode, sl.date, qty = sum(sd.qty), bonus = 0, value = sum(sd.qty * sd.saleprice) FROM receiptheader sl, receiptdetail sd WHERE sl.posted = 'Y' AND sl.receiptinvcode = sd.receiptinvcode AND sl.date >= '2024-01-01' and sl.date <= '2024-01-07' Group By sd.icode, sl.date UNION ALL select type='AI', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = 0, value = sum(sd.looseqty * sd.price) FROM Adjheader sl, Adjdetail sd WHERE sl.posted = 'Y' AND sl.Adjcode = sd.Adjcode and sl.Adjcatcode = 1 AND sl.date >= '2024-01-01' and sl.date <= '2024-01-07' Group By sd.icode, sl.date UNION ALL select type='AD', sd.icode, sl.date, qty = sum(sd.looseqty), bonus = 0, value = sum(sd.looseqty * sd.price) FROM Adjheader sl, Adjdetail sd WHERE sl.posted = 'Y' AND sl.Adjcode = sd.Adjcode and sl.Adjcatcode = 2 AND sl.date >= '2024-01-01' and sl.date <= '2024-01-07' Group By sd.icode, sl.date UNION ALL SELECT type='OP', icode, date=null, qty = 0, bonus = 0, value=0 FROM ITEM) AS St ON (I.ICode = ST.ICode), itemcategory ic WHERE i.active=1 and (CASE 'M' WHEN 'M' THEN I.MANFCODE WHEN 'C' THEN I.ICatCode WHEN 'L' THEN I.ICCode ELSE I.PACKCODE END) IN (1) and i.icatcode = ic.icatcode GROUP BY St.icode, i.name, i.customicode, i.icatcode, i.iccode, i.manfcode, i.packcode, i.saleprice, i.purprice, i.avgprice, i.packunits ORDER BY groupname, groupcode, itemname, aliasname, icode;
